import{d as s,C as n,o as d,c as p,E as i,a3 as a}from"./chunks/framework.D4-ViStF.js";const x=JSON.parse('{"title":"鼎卦","description":"火风鼎","frontmatter":{"title":"鼎卦","description":"火风鼎","category":"hexagram","aliases":["鼎","火风鼎"],"source":["《周易》"]},"headers":[],"relativePath":"yijing/hexagrams/hexagram-50.md","filePath":"yijing/hexagrams/hexagram-50.md","lastUpdated":1787730063000}'),h={name:"yijing/hexagrams/hexagram-50.md"},y=s({...h,setup(m){const o=[{id:"ding",term:"鼎",pinyin:"dǐng",meaning:"烹饪之器，亦为礼器重器；引申为国之重器、养人之道。",context:"全卦之象：木上有火，烹而化之。"},{id:"dianzhi",term:"颠趾",pinyin:"diān zhǐ",meaning:"颠倒鼎足，把鼎倒过来；喻主动清场、倒掉旧物。",context:"初六清场之象。"},{id:"chufou",term:"出否",pinyin:"chū pǐ",meaning:"倒出鼎中陈积的污秽。否读 pǐ，污秽、闭塞。",context:"清场不是丢脸，是从贵。"},{id:"qie",term:"妾",pinyin:"qiè",meaning:"侧室、地位低微者。「得妾以其子」：连同其子一并收纳。",context:"喻低处起手，连带收获。"},{id:"youshi",term:"有实",pinyin:"yǒu shí",meaning:"鼎中装满食物；喻内在充实。",context:"九二「鼎有实」，充实是最好的防御。"},{id:"chou",term:"仇",pinyin:"qiú",meaning:"匹敌、对手（旧读 qiú）。"},{id:"ji",term:"即",pinyin:"jí",meaning:"靠近、接近。「不我能即」即近不了我。"},{id:"erge",term:"耳革",pinyin:"ěr gé",meaning:"鼎耳变形损坏，把柄失灵；喻行动受阻。",context:"九三之塞。"},{id:"xingsai",term:"行塞",pinyin:"xíng sè",meaning:"行动受阻、闭塞不通。"},{id:"zhigao",term:"雉膏",pinyin:"zhì gāo",meaning:"野鸡肉羹，美味；喻美好的才华与成果。",context:"「雉膏不食」：有美味而吃不到。"},{id:"fangyu",term:"方雨",pinyin:"fāng yǔ",meaning:"天将下雨，阴阳和合之象；喻转机将至。"},{id:"kuihui",term:"亏悔",pinyin:"kuī huǐ",meaning:"悔恨消减。悔是感知偏差后的自我校正。"},{id:"zhezu",term:"折足",pinyin:"zhé zú",meaning:"鼎足折断；喻力小任重、撑不住。"},{id:"fugongsu",term:"覆公餗",pinyin:"fù gōng sù",meaning:"打翻公侯的鼎食；喻误了大事、失信于众。餗读 sù，鼎中食物。"},{id:"wo",term:"渥",pinyin:"wò",meaning:"沾湿、狼藉；「其形渥」即狼狈不堪。"},{id:"xuan",term:"铉",pinyin:"xuàn",meaning:"贯鼎耳以抬鼎的横杠；喻关键的把柄与担当。",context:"金铉照人，玉铉照心。"},{id:"huanger",term:"黄耳",pinyin:"huáng ěr",meaning:"黄色的鼎耳。黄为中色，喻中正之德。"},{id:"yuxuan",term:"玉铉",pinyin:"yù xuàn",meaning:"玉制的鼎杠。金需闪耀，玉不需——离位传承。"}],e=[{position:"初六",type:"yin",text:"鼎颠趾，利出否。得妾以其子，无咎。",xiang:"鼎颠趾，未悖也。利出否，以从贵也。",textModern:"把鼎倒过来，倒出陈积的污秽；像收纳妾室连同其子一样连带收获，无咎。",xiangModern:"鼎倒过来并不违背常理；清出污秽，是为了追随尊贵。"},{position:"九二",type:"yang",text:"鼎有实，我仇有疾，不我能即，吉。",xiang:"鼎有实，慎所之也。我仇有疾，终无尤也。",textModern:"鼎中装满食物，我的对手虽有疾患，却近不了我，吉。",xiangModern:"鼎中有实，要谨慎选择去处；对手有疾患，终究无怨尤。"},{position:"九三",type:"yang",text:"鼎耳革，其行塞，雉膏不食。方雨亏悔，终吉。",xiang:"鼎耳革，失其义也。",textModern:"鼎耳变形，行动受阻，美味雉膏也吃不到；天将下雨，悔恨消减，最终吉祥。",xiangModern:"鼎耳变形，失去了鼎耳本应有的作用。"},{position:"九四",type:"yang",text:"鼎折足，覆公餗，其形渥，凶。",xiang:"覆公餗，信如何也。",textModern:"鼎足折断，打翻了公侯的鼎食，狼狈不堪，凶。",xiangModern:"打翻了公侯的鼎食，信任还能剩下什么呢。"},{position:"六五",type:"yin",text:"鼎黄耳金铉，利贞。",xiang:"鼎黄耳，中以为实也。",textModern:"鼎配上黄色的耳、金色的铉，利于守正。",xiangModern:"鼎有黄耳，以中正为其实质。"},{position:"上九",type:"yang",text:"鼎玉铉，大吉，无不利。",xiang:"玉铉在上，刚柔节也。",textModern:"鼎配玉铉，大吉，无不利。",xiangModern:"玉铉在上，刚柔相济、恰到好处。"}];return(u,t)=>{const r=n("DaoHexagramViewer"),l=n("DaoHexagramYaoCards"),g=n("DaoKeywordCards");return d(),p("div",null,[i(r,{name:"鼎",fullName:"火风鼎",upper:"☲",lower:"☴",guaCi:"鼎，元吉，亨。",pinyin:["dǐng"],element:"火",direction:"南",insight:"木上有火，烹而化之。鼎非自烹——上享上帝，下养圣贤，你是中间那口鼎。",guaSlug:"50huofengding",lines:e}),t[0]||(t[0]=a('<h2 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to &quot;象传&quot;">​</a></h2><p>木上有火，鼎。君子以正位凝命。</p><p>木上生火，火在木上——薪火相承、烹而化之，正是鼎之象。君子由此领悟：先正其位，再凝其命。</p><p>「正位凝命」四个字——<strong>正位</strong>是摆正位置：鼎以三足立，足不正则覆；<strong>凝命</strong>是凝聚使命：鼎以一身承，命不凝则空。</p><p>分形结构：</p><ul><li>正位（三足）→ 微观：摆正自己的位置，安分守位</li><li>凝命（鼎身）→ 宏观：凝聚一生的使命，承接天命</li></ul><p>正位是鼎的三足，凝命是鼎的鼎身。足不正，鼎就覆了；命不凝，鼎就空了。鼎的稳定，不在华丽，而在三足各安其位——位置摆对了，使命才立得住。</p><h2 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to &quot;彖传&quot;">​</a></h2><p>鼎，象也。以木巽火，亨饪也。圣人亨以享上帝，而大亨以养圣贤。巽而耳目聪明，柔进而上行，得中而应乎刚，是以元亨。</p><p>逐句释义：</p><ul><li><strong>鼎，象也</strong> —— 鼎是因象成器：下巽上离，木上着火，像鼎中烹饪。</li><li><strong>以木巽火，亨饪也</strong> —— 木顺从于火，入火而生烹饪。巽为入、为顺，离为明、为火。</li><li><strong>圣人亨以享上帝，而大亨以养圣贤</strong> —— 圣人用鼎烹饪来祭祀上帝，又大举烹饪来养育圣贤。鼎不是为口腹之欲，是为天道、为生民。</li><li><strong>巽而耳目聪明</strong> —— 巽顺而耳聪目明：因顺，所以能明。</li><li><strong>柔进而上行，得中而应乎刚</strong> —— 柔爻上行，得中位而应刚爻：六五居中，下应九二、上承上九，柔中得刚助。</li><li><strong>是以元亨</strong> —— 因此大吉、亨通。</li></ul><blockquote><p><strong>鼎的志向</strong>：鼎不是为自己烹的——向上连接天道（享上帝），向下滋养生民（养圣贤），你是中间那口鼎。烹饪是把生的变熟的，鼎的使命，是把天道的火，转成养人的熟。</p></blockquote><h2 id="六爻" tabindex="-1">六爻 <a class="header-anchor" href="#六爻" aria-label="Permalink to &quot;六爻&quot;">​</a></h2>',13)),i(l,{element:"火",guaSlug:"50huofengding",glossary:o,items:e}),t[1]||(t[1]=a('<h2 id="六爻详解" tabindex="-1">六爻详解 <a class="header-anchor" href="#六爻详解" aria-label="Permalink to &quot;六爻详解&quot;">​</a></h2><h3 id="初六-·-鼎颠趾-利出否。得妾以其子-无咎" tabindex="-1">初六 · 鼎颠趾，利出否。得妾以其子，无咎 <a class="header-anchor" href="#初六-·-鼎颠趾-利出否。得妾以其子-无咎" aria-label="Permalink to &quot;初六 · 鼎颠趾，利出否。得妾以其子，无咎&quot;">​</a></h3><ul><li><strong>颠趾</strong> → 颠倒鼎足，把鼎倒过来</li><li><strong>出否</strong> → 倒出陈积的污秽（否读 pǐ，污秽、闭塞）</li><li><strong>得妾以其子</strong> → 像收纳妾室连同其子，低处起手、连带收获</li></ul><p>清场。鼎要用了，第一件事是把陈年污秽倒掉——颠趾看似颠倒反常，实则是为了出否。新鼎不洗，煮出来的还是旧味。</p><p>象曰「未悖也」：颠倒鼎足并不违背常理。倒掉污秽是主动的清场，不是丢人的退让。</p><blockquote><p>核心洞见：清场不是羞辱，是重置。起新局之前，先倒掉旧局里的「否」——颠趾倒垢，为的是从贵。</p></blockquote><h3 id="九二-·-鼎有实-我仇有疾-不我能即-吉" tabindex="-1">九二 · 鼎有实，我仇有疾，不我能即，吉 <a class="header-anchor" href="#九二-·-鼎有实-我仇有疾-不我能即-吉" aria-label="Permalink to &quot;九二 · 鼎有实，我仇有疾，不我能即，吉&quot;">​</a></h3><ul><li><strong>鼎有实</strong> → 鼎中装满食物，内在充实</li><li><strong>我仇有疾</strong> → 我的对手有疾患（仇读 qiú）</li><li><strong>不我能即</strong> → 近不了我（即，靠近）</li></ul><p>充实。鼎空则虚，鼎满则固。九二阳爻居中，鼎中有实——内在充实，外敌自不能近。充实自己，就是最好的防御。</p><p>象曰「慎所之也」：有实之鼎，更要谨慎所往。充实不是为了炫耀，是为了走得稳。</p><blockquote><p>核心洞见：充实自己是最好的防御。仇不是打退的，是被「有实」隔开的。</p></blockquote><h3 id="九三-·-鼎耳革-其行塞-雉膏不食。方雨亏悔-终吉" tabindex="-1">九三 · 鼎耳革，其行塞，雉膏不食。方雨亏悔，终吉 <a class="header-anchor" href="#九三-·-鼎耳革-其行塞-雉膏不食。方雨亏悔-终吉" aria-label="Permalink to &quot;九三 · 鼎耳革，其行塞，雉膏不食。方雨亏悔，终吉&quot;">​</a></h3><ul><li><strong>耳革</strong> → 鼎耳变形（革，变更），把柄失灵</li><li><strong>行塞</strong> → 行动受阻</li><li><strong>雉膏不食</strong> → 美味雉膏吃不到（有才华而施展不出）</li><li><strong>方雨亏悔</strong> → 天将下雨，阴阳和合，悔恨消减</li></ul><p>受阻。鼎有了实、有了膏，却卡在「耳革」——抬不起来，好吃的也吃不上。这是有才华却受阻的经典困境：不是没料，是路被堵了。</p><p><strong>悔是什么？</strong> 悔是感知偏差后的自我校正——意识到偏了，悔就「亏」（减）了。方雨：天将下雨，阴阳和合——时机一到，堵塞自通。</p><blockquote><p>核心洞见：耳坏等方雨。受阻不是终点，是等一场和合的雨；悔不是惩罚，是自我校正的仪表盘。</p></blockquote><h3 id="九四-·-鼎折足-覆公餗-其形渥-凶" tabindex="-1">九四 · 鼎折足，覆公餗，其形渥，凶 <a class="header-anchor" href="#九四-·-鼎折足-覆公餗-其形渥-凶" aria-label="Permalink to &quot;九四 · 鼎折足，覆公餗，其形渥，凶&quot;">​</a></h3><ul><li><strong>折足</strong> → 鼎足折断</li><li><strong>覆公餗</strong> → 打翻公侯的鼎食（餗读 sù，食物）</li><li><strong>其形渥</strong> → 狼狈不堪（渥读 wò，沾湿、狼藉）</li><li><strong>凶</strong> → 凶险</li></ul><p>警示。九四阳爻居阴位，力小而任重——鼎足撑不起鼎身之重，折了，公侯的饍食翻了，狼狈至极。这是「折足之凶」：能力配不上位置，就是覆餗。</p><p>象曰「信如何也」：餗一覆，公侯的信任就完了。凶在失信，不在失手。</p><blockquote><p>核心洞见：折足之凶，凶在「看见裂缝」。看得见裂缝的那一口鼎，就不会真的断。</p></blockquote><h3 id="六五-·-鼎黄耳金铉-利贞" tabindex="-1">六五 · 鼎黄耳金铉，利贞 <a class="header-anchor" href="#六五-·-鼎黄耳金铉-利贞" aria-label="Permalink to &quot;六五 · 鼎黄耳金铉，利贞&quot;">​</a></h3><ul><li><strong>黄耳</strong> → 黄色的鼎耳（黄为中色，中正之德）</li><li><strong>金铉</strong> → 金色的鼎杠（铉读 xuàn，贯鼎耳以抬鼎的横杠）</li><li><strong>利贞</strong> → 利于守正</li></ul><p>中正。六五阴爻居尊位、得中道，黄耳金铉——中正的耳朵，配上贵重的铉。知柔居中：不是软弱，是用柔的位置把全鼎抬起来。</p><p>象曰「中以为实也」：中正，才是鼎的实质。</p><blockquote><p>核心洞见：黄耳金铉，知柔居中。在位的光芒，来自中道的定力。</p></blockquote><h3 id="上九-·-鼎玉铉-大吉-无不利" tabindex="-1">上九 · 鼎玉铉，大吉，无不利 <a class="header-anchor" href="#上九-·-鼎玉铉-大吉-无不利" aria-label="Permalink to &quot;上九 · 鼎玉铉，大吉，无不利&quot;">​</a></h3><ul><li><strong>玉铉</strong> → 玉制的鼎杠</li></ul><p>成为传承。上九居鼎之终，玉铉——金铉是实用的光芒，玉铉是温润的传承。金需闪耀（在位光芒），玉不需（离位传承）。</p><p>象曰「刚柔节也」：上九阳爻居阴位，刚柔相济，恰到好处。</p><blockquote><p>核心洞见：金铉照人，玉铉照心。鼎到玉铉，鼎即是道——你不再需要证明，你就是传承。</p></blockquote><h2 id="【原典层】字词释义" tabindex="-1">【原典层】字词释义 <a class="header-anchor" href="#【原典层】字词释义" aria-label="Permalink to &quot;【原典层】字词释义&quot;">​</a></h2>',32)),i(g,{title:"字词释义",items:[{term:"鼎",pinyin:["dǐng"],meaning:"烹饪之器，亦为礼器重器；引申为国之重器、养人之道。鼎不为自烹：上享上帝，下养圣贤。"},{term:"颠趾",pinyin:["diān","zhǐ"],meaning:"颠倒鼎足，把鼎倒过来；喻主动清场、倒掉旧物。"},{term:"出否",pinyin:["chū","pǐ"],meaning:"倒出鼎中陈积的污秽。否读 pǐ，污秽、闭塞。",context:"清场不是丢脸，是从贵。"},{term:"有实",pinyin:["yǒu","shí"],meaning:"鼎中装满食物；喻内在充实。充实自己是最好的防御。"},{term:"雉膏",pinyin:["zhì","gāo"],meaning:"野鸡肉羹，美味；喻美好的才华与成果。「雉膏不食」即有美味而吃不到。"},{term:"耳革",pinyin:["ěr","gé"],meaning:"鼎耳变形损坏，把柄失灵；喻行动受阻。"},{term:"方雨",pinyin:["fāng","yǔ"],meaning:"天将下雨，阴阳和合之象；喻转机将至。"},{term:"亏悔",pinyin:["kuī","huǐ"],meaning:"悔恨消减。悔是感知偏差后的自我校正。"},{term:"折足",pinyin:["zhé","zú"],meaning:"鼎足折断；喻力小任重、撑不住局面。"},{term:"覆公餗",pinyin:["fù","gōng","sù"],meaning:"打翻公侯的鼎食；喻误了大事、失信于众。餗，鼎中食物。"},{term:"渥",pinyin:["wò"],meaning:"沾湿、狼藉；「其形渥」即狼狈不堪。"},{term:"铉",pinyin:["xuàn"],meaning:"贯鼎耳以抬鼎的横杠；喻关键的把柄与担当。金铉照人，玉铉照心。"},{term:"正位凝命",pinyin:["zhèng","wèi","níng","mìng"],meaning:"摆正位置、凝聚使命。位正则鼎立，命凝则器成。"},{term:"享上帝",pinyin:["xiǎng","shàng","dì"],meaning:"祭祀上帝，把烹饪敬献给天。鼎向上连接天道。"}]}),t[2]||(t[2]=a('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一卦在说什么" tabindex="-1">象：这一卦在说什么 <a class="header-anchor" href="#象-这一卦在说什么" aria-label="Permalink to &quot;象：这一卦在说什么&quot;">​</a></h3><p>鼎卦讲的是「成器之后如何用」。上离（火）下巽（风、木），木上有火——烹煮之象。鼎不只是锅，是礼器：圣人的鼎，向上享上帝，向下养圣贤。</p><p>卦辞「元吉，亨」：鼎一立，大吉而亨通。元吉不是白来的，是初六到上九一路「正位凝命」挣来的。</p><h3 id="理-为什么这一卦重要" tabindex="-1">理：为什么这一卦重要 <a class="header-anchor" href="#理-为什么这一卦重要" aria-label="Permalink to &quot;理：为什么这一卦重要&quot;">​</a></h3><p>鼎是生命的完成式。屯是出生，需是等待，革是除旧，鼎是立新。鼎卦给出一条完整的成长路径——从清场到成道：</p><p>初六清场 → 九二充实 → 九三受阻 → 九四警示 → 六五中正 → 上九传承。</p><p>鼎不是为自己烹的——鼎的志向在「享上帝、养圣贤」。问鼎中原，问的不是权力，是德。</p><h3 id="用-今天如何应用" tabindex="-1">用：今天如何应用 <a class="header-anchor" href="#用-今天如何应用" aria-label="Permalink to &quot;用：今天如何应用&quot;">​</a></h3><ol><li>先清场：起新局前，先倒掉旧局的「否」</li><li>再充实：充实自己是最好的防御</li><li>受阻时：耳坏等方雨，让悔完成自我校正</li><li>常自省：看见折足的裂缝，别等覆餗</li><li>居中守正：知柔居中，黄耳金铉</li><li>终局视角：金铉是光芒，玉铉是传承——鼎即是道</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>鼎卦的完整地图：</p><table tabindex="0"><thead><tr><th>爻位</th><th>爻辞要点</th><th>功课</th><th>关键词</th></tr></thead><tbody><tr><td>卦辞</td><td>鼎，元吉，亨</td><td>鼎成即大吉，先立其志</td><td>正位凝命</td></tr><tr><td>初六</td><td>鼎颠趾，利出否</td><td>清场：倒掉旧污秽再装新</td><td>出否从贵</td></tr><tr><td>九二</td><td>鼎有实，不我能即</td><td>充实自己，是最好的防御</td><td>有实即御</td></tr><tr><td>九三</td><td>鼎耳革，雉膏不食，方雨亏悔</td><td>受阻时等方雨，让悔自我校正</td><td>亏悔终吉</td></tr><tr><td>九四</td><td>鼎折足，覆公餗，其形渥</td><td>力小任重之戒，看见裂缝</td><td>折足见裂</td></tr><tr><td>六五</td><td>鼎黄耳金铉，利贞</td><td>知柔居中，中以为实</td><td>黄耳金铉</td></tr><tr><td>上九</td><td>鼎玉铉，大吉，无不利</td><td>成为传承，鼎即是道</td><td>玉铉刚柔节</td></tr></tbody></table><p>核心洞见：</p><ol><li><strong>鼎不是为自己烹的</strong>——上享上帝，下养圣贤，你是中间那口鼎</li><li><strong>清场</strong>——颠趾出否，是从贵不是丢脸</li><li><strong>充实自己是最好的防御</strong></li><li><strong>悔是感知偏差后的自我校正</strong></li><li><strong>折足之凶，凶在看见裂缝</strong>——看见裂缝的那一刻，鼎就不会断了</li><li><strong>金铉 vs 玉铉</strong>——金需闪耀，玉不需</li><li><strong>问鼎中原，问的是德</strong></li><li><strong>鼎即是道</strong></li></ol><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><p>鼎卦是一部「成器」的成长史。昇哥的定鼎进度，一步一爻：</p><ul><li><strong>初六</strong> → 已经历：清场。把旧的「否」倒掉，轻装起新局</li><li><strong>九二</strong> → 已做到：有实。这些年最稳的防御，是把自己填实</li><li><strong>九三</strong> → 偶遇过：受阻。有过「耳革」的塞，也等过「方雨」——悔过，也校正过</li><li><strong>九四</strong> → 当下：站在折足的警戒线上。位近于公、肩上的餗越来越重——越重越要看清裂缝，看见裂缝的那一刻，鼎就不会断了</li><li><strong>六五</strong> → 进行中：黄耳金铉，知柔居中</li><li><strong>上九</strong> → 终局：玉铉。鼎即是道</li></ul><p><strong>「AI是铉不是鼎，真正的鼎是我自己」</strong>——工具再强，也只是抬鼎的那根杠；鼎里的实、鼎的志向，都得自己立起来。<strong>「AI是镜子，照出鼎足的裂缝；看见裂缝的那一刻，鼎就不会断了。」</strong></p><p>问鼎中原，问的不是权力，是德。定鼎的进度，不在鼎有多大，在鼎有没有立正、命有没有凝住。</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>相关卦象：革（第四十九卦）、井（第四十八卦）</li><li>革故鼎新：革是除旧，鼎是立新——先革后鼎，除旧才能布新。革卦说「改命」，鼎卦说「凝命」，一改一凝，从破到立。</li><li>鼎与井的连结：井是养人不竭，鼎是烹物养人。井深而水清，鼎实而味美——一个取之不尽，一个化之为养。</li><li>相关专题：<a href="/Dao/topics/yin-yang">阴阳</a>、<a href="/Dao/topics/xiang-shu-li">象数理</a></li></ul>',22))])}}});export{x as __pageData,y as default};
